package app;

import dagger.Component;
import javax.inject.Inject;

public final class Main {
    static final class Greeter {
        @Inject
        Greeter() {
        }

        String greet(String name) {
            return "Hello, " + name;
        }
    }

    @Component
    interface AppComponent {
        Greeter greeter();
    }

    public static void main(String[] args) {
        // DaggerMain_AppComponent is generated by dagger-compiler
        System.out.println(DaggerMain_AppComponent.create().greeter().greet("Dagger"));
    }
}
